import { encodePage1MarkdownSnapshot, decodePage1MarkdownSnapshot } from './page1MarkdownSnapshot.js';
import { createWardrobeRecoveryContext, wardrobeItemRecoveryScope, recoverWardrobeColors } from './wardrobeColorRecovery.js';
import { isImportedPersonKey } from '../../lib/observationCaptureImport.js';
import { accessoryRestoreNotices } from '../../lib/engine/accessoryPolicy.js';
import { matchResolvedOuterwear } from '../../lib/engine/outerwearModel.js';
import { isUnderbustTopFit, matchResolvedUnderbustTop, UNDERBUST_UNTUCKED_SOURCE } from '../../lib/engine/underbustTopFit.js';
import {
  createEmptyLocks,
  getLockControls,
  normalizeLocks,
} from '../../lib/engine.js';
import { MIDJOURNEY_PARAMETER_CONTRACT } from '../../lib/engine/midjourneyParameterContract.js';
import { framingAspectRatioForSelection, parseMidjourneyParameterTail } from '../../lib/engine/midjourneyParameterTail.js';
import {
  Z_IMAGE_VISIBLE_TEXT_SELECTION_KEYS,
  parseZImageVisibleTextSentence,
} from '../../lib/engine/zImageVisibleText.js';
import { ACTION_POSE_CARDS, buildActionPoseSavedCard } from '../../lib/actionPoseLab.js';
import { reconcilePage1SingleWardrobeLocks } from '../page1/page1WardrobeExclusivity.js';
import { normalizeZImageDisplayLabel } from './promptLabels.js';
import { isHeadDominantFraming, matchHeadDominantAngle } from '../../lib/engine/headDominantFraming.js';
import { SPECIFIED_ACTION_CONCRETE_OPTIONS, getSpecifiedActionEffectiveLocks } from '../../lib/engine/specifiedActions.js';

export const FAVORITES_STORAGE_VERSION = 3;
const READABLE_FAVORITES_STORAGE_VERSIONS = Object.freeze([2, FAVORITES_STORAGE_VERSION, 4]);

const OPTIONAL_SILENCE_LOCK_PATTERN = /^(bodyType|hairStylingState)[AB]?Id$|^outerwear[AB]?OpeningId$|^eyewear[AB]?PlacementId$|^sceneAttributeId$/;

const STRUCTURED_CONTROL_KEYS = {
  Style: ['imageTypePresetId', 'styleId'],
  Character: [
    'subjectCount', 'specialSubjectId', 'characterProfileId',
    'bodyTypeId', 'bodyTypeAId', 'bodyTypeBId',
    'facialFeaturesId', 'facialFeaturesAId', 'facialFeaturesBId',
    'skinDetailsId', 'skinDetailsAId', 'skinDetailsBId',
    'hairstyleId', 'hairstyleAId', 'hairstyleBId',
    'hairStylingStateId', 'hairStylingStateAId', 'hairStylingStateBId',
    'hairColorId', 'hairColorAId', 'hairColorBId',
    'duoPoseId', 'duoPoseBaseId', 'duoExpressionId', 'expressionId',
    'poseBaseId', 'specifiedActionId', 'poseOrientationId', 'poseArrangementId', 'poseHandId', 'posePropId', 'poseHeadId', 'poseAnchorId',
  ],
  Wardrobe: [
    'nosePiercingId', 'lipPiercingId',
    'specialOutfitId', 'specialOutfitAId', 'specialOutfitBId',
    'completeLookPaletteId', 'completeLookPaletteAId', 'completeLookPaletteBId',
    'outfitPresetId', 'outfitPresetColorId',
    'outfitPresetAId', 'outfitPresetAColorId',
    'outfitPresetBId', 'outfitPresetBColorId',
    'outfitPresetPrimaryColorId', 'outfitPresetContrastColorId', 'outfitPresetLockedPaletteId',
    'outfitPresetAPrimaryColorId', 'outfitPresetAContrastColorId', 'outfitPresetALockedPaletteId',
    'outfitPresetBPrimaryColorId', 'outfitPresetBContrastColorId', 'outfitPresetBLockedPaletteId',
    'topId', 'topAId', 'topBId',
    'topFitId', 'topFitAId', 'topFitBId',
    'topStylingId', 'topStylingAId', 'topStylingBId',
    'topBottomPaletteId', 'topBottomPaletteAId', 'topBottomPaletteBId',
    'topColorId', 'topAColorId', 'topBColorId',
    'topPatternId', 'topAPatternId', 'topBPatternId',
    'dressId', 'dressAId', 'dressBId',
    'dressColorId', 'dressAColorId', 'dressBColorId',
    'pantsId', 'pantsAId', 'pantsBId',
    'skirtId', 'skirtAId', 'skirtBId',
    'bottomFitId', 'bottomFitAId', 'bottomFitBId',
    'bottomRiseId', 'bottomRiseAId', 'bottomRiseBId',
    'bottomColorId', 'bottomAColorId', 'bottomBColorId',
    'bottomPatternId', 'bottomAPatternId', 'bottomBPatternId',
    'outerwearId', 'outerwearFitId', 'outerwearColorId', 'outerwearPatternId',
    'outerwearOpeningId', 'outerwearStylingId', 'legwearId', 'legwearColorId',
    'shoesId', 'shoesColorId',
    'outerwearAId', 'outerwearAFitId', 'outerwearAColorId', 'outerwearAPatternId',
    'outerwearAOpeningId', 'outerwearAStylingId', 'legwearAId', 'legwearAColorId',
    'shoesAId', 'shoesAColorId',
    'outerwearBId', 'outerwearBFitId', 'outerwearBColorId', 'outerwearBPatternId',
    'outerwearBOpeningId', 'outerwearBStylingId', 'legwearBId', 'legwearBColorId',
    'shoesBId', 'shoesBColorId',
    'headphonesId', 'headphonesColorId', 'faceCoveringId', 'faceCoveringColorId', 'headAccessoryId', 'headAccessoryColorId', 'eyewearId', 'eyewearColorId', 'earringsId', 'neckAccessoryId',
    'headphonesAId', 'headphonesAColorId', 'faceCoveringAId', 'faceCoveringAColorId', 'headAccessoryAId', 'headAccessoryAColorId', 'eyewearAId', 'eyewearAColorId', 'eyewearAPlacementId', 'earringsAId', 'neckAccessoryAId', 'waistAccessoryAId',
    'headphonesBId', 'headphonesBColorId', 'faceCoveringBId', 'faceCoveringBColorId', 'headAccessoryBId', 'headAccessoryBColorId', 'eyewearBId', 'eyewearBColorId', 'eyewearBPlacementId', 'earringsBId', 'neckAccessoryBId', 'waistAccessoryBId',
    'wristAccessoryId', 'ringId', 'waistAccessoryId',
  ],
  Location: [
    'sceneAttributeId', 'fixedCompositionSetId', 'fixedSetPositionId',
    'fixedSetCaptureModeId', 'fixedSetPerformanceStateId', 'locationId',
  ],
  Framing: ['framingId', 'angleId', 'orbitId', 'lensId'],
  Lighting: ['lightingId', 'lightDirectionId'],
  'Camera & Film': ['cameraSystemId', 'filmId', 'opticalEffectId'],
};

export function buildMarkdownExport(data) {
  const labels = {
    midjourney: data.promptLabels?.midjourney || 'AI Prompt',
    grok: data.promptLabels?.grok || 'Gpt',
    zImage: normalizeZImageDisplayLabel(data.promptLabels?.zImage, 'Z-Image'),
  };
  const structured = data.structured && typeof data.structured === 'object' ? data.structured : {};
  const extraPromptEntries = Array.isArray(data.extraPrompts)
    ? data.extraPrompts.map((entry) => ({ label: entry.label, text: entry.text }))
    : [];
  const promptEntries = [
    { label: labels.midjourney, text: data.midjourneyPrompt },
    { label: labels.grok, text: data.grokPrompt },
    { label: labels.zImage, text: data.zImagePrompt },
    ...(data.nanoBananaPrompt?.trim() ? [{ label: 'Nano Banana 2.1', text: data.nanoBananaPrompt }] : []),
    ...extraPromptEntries,
  ].filter((entry) => entry.text);

  // Empty visual content cannot encode its silence choice in the prose itself.
  const silenceLocks = Object.fromEntries(getLockControls().filter((control) => (
    OPTIONAL_SILENCE_LOCK_PATTERN.test(control.key)
    && control.options?.some((option) => option.id === data.selection?.[control.key] && option.zh === '全無')
  )).map((control) => [control.key, data.selection[control.key]]));
  const silenceMetadata = Object.keys(silenceLocks).length
    ? `<!-- VPStudio Optional Silence: ${JSON.stringify(silenceLocks)} -->\n` : '';

  const captureMetadata = data.selection?.captureMode === 'observation'
    ? `<!-- VPStudio Observation Capture: ${JSON.stringify(data.selection).replace(/</g, '\\u003c').replace(/>/g, '\\u003e')} -->\n` : '';

  return `${encodePage1MarkdownSnapshot(data)}${silenceMetadata}${captureMetadata}# Generated Prompt - ${new Date(data.date).toLocaleString()}
**Source:** ${data.sourceLabel || 'Prompt 工作台'}
**Summary:** ${data.summary}

${promptEntries.map((entry) => `## ${entry.label}
\`\`\`text
${entry.text}
\`\`\``).join('\n\n')}

---

## Structured Scheme
${Object.entries(structured)
  .map(([key, items]) => {
    const text = items.map((item) => `${item.en} (${item.zh})`).join(', ');
    return `* **${key}:** ${text || '-'}`;
  })
  .join('\n')}
`;
}

const STRUCTURED_TAG_CATEGORIES = {
  Style: '風格',
  Character: '主體',
  Wardrobe: '服裝',
  Location: '場景',
  Framing: '構圖',
  Lighting: '光影',
  'Lens & Imaging': '鏡頭',
  'Camera & Film': '鏡頭',
  'Action Pose': '動作',
  'Negative Pose Guard': '動作',
  'Framing Hint': '構圖',
  'Page3 Scene': '場景',
};

const SOURCE_TAG_CATEGORIES = {
  page1: '來源',
  page2: '角色',
  page3: '場景',
  actionPose: '動作',
};

const MANIFEST_SUMMARY_KEYS = ['style', 'character', 'wardrobe', 'location', 'camera', 'lighting'];

const MANIFEST_SUMMARY_ALIASES = {
  style: ['style'],
  character: ['character', 'characterDna'],
  wardrobe: ['wardrobe'],
  location: ['location', 'sceneLook'],
  camera: ['camera'],
  lighting: ['lighting'],
};

function humanizeTagId(tagId) {
  const text = String(tagId || '').trim();
  if (!text) return '';
  if (/[^a-z0-9_-]/i.test(text)) return text;
  return text
    .replace(/[_-]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .split(' ')
    .map((word) => word ? `${word.charAt(0).toUpperCase()}${word.slice(1)}` : '')
    .join(' ');
}

function normalizeManifestValue(value) {
  const text = String(value ?? '').trim();
  return text === '-' || text === '全無' ? '' : text;
}

function getSourceTagCategory(source) {
  return SOURCE_TAG_CATEGORIES[source] || '來源';
}

function normalizeSourceTag(tag, category = '來源') {
  if (typeof tag === 'string') {
    const id = tag.trim();
    return id ? { id, category, label: humanizeTagId(id) || id } : null;
  }
  if (!tag || typeof tag !== 'object') return null;

  const id = String(tag.id || tag.key || tag.label || tag.zh || '').trim();
  if (!id) return null;
  return {
    id,
    category: String(tag.category || category || '來源').trim() || '來源',
    label: String(tag.label || tag.zh || humanizeTagId(id) || id).trim() || id,
  };
}

export function collectSourceTags(data) {
  const tags = [];
  const seenTagIds = new Set();
  const sourceCategory = getSourceTagCategory(data?.source);
  const addTag = (tag, category) => {
    const normalized = normalizeSourceTag(tag, category);
    if (!normalized || ['none', 'random'].includes(normalized.id)) return;
    if (seenTagIds.has(normalized.id)) return;
    seenTagIds.add(normalized.id);
    tags.push(normalized);
  };

  (Array.isArray(data?.sourceTags) ? data.sourceTags : []).forEach((tag) => addTag(tag, tag?.category || sourceCategory));
  (Array.isArray(data?.tags) ? data.tags : []).forEach((tag) => addTag(tag, tag?.category || sourceCategory));

  Object.entries(data?.structured || {}).forEach(([section, items]) => {
    const category = STRUCTURED_TAG_CATEGORIES[section] || section;
    (Array.isArray(items) ? items : []).forEach((item) => {
      (Array.isArray(item?.meta?.tags) ? item.meta.tags : []).forEach((tag) => addTag(tag, category));
    });
  });

  return tags;
}

export function normalizeManifestSummaryFields(data) {
  const sourceFields = data?.summaryFields && typeof data.summaryFields === 'object'
    ? data.summaryFields
    : {};
  const parsedFields = parseSummaryFields(data?.summary);

  return Object.fromEntries(MANIFEST_SUMMARY_KEYS.map((key) => {
    const value = MANIFEST_SUMMARY_ALIASES[key]
      .map((alias) => sourceFields[alias])
      .concat(parsedFields[key])
      .map(normalizeManifestValue)
      .find(Boolean) || '';
    return [key, value];
  }));
}

export function buildSavedCardManifestItem(data, file) {
  return {
    sourceId: String(data?.id || ''),
    file: String(file || ''),
    title: String(data?.title || data?.summary || data?.sourceLabel || '').trim(),
    source: String(data?.source || 'page1'),
    sourceLabel: String(data?.sourceLabel || 'Prompt 工作台'),
    summary: String(data?.summary || ''),
    summaryFields: normalizeManifestSummaryFields(data),
    tags: collectSourceTags(data),
  };
}

export function parseSummaryFields(summary) {
  const text = String(summary || '');
  const labels = {
    style: '風格',
    character: '人物',
    wardrobe: '服裝',
    location: '場景',
    camera: '鏡頭',
    lighting: '光影',
  };

  return Object.fromEntries(
    Object.entries(labels).map(([key, label]) => {
      const match = text.match(new RegExp(`${label}：([^|]+)`));
      return [key, match ? match[1].trim() : '-'];
    })
  );
}

export function buildImportedStructured(locks, controls) {
  locks = getSpecifiedActionEffectiveLocks(locks);
  const controlMap = new Map(controls.map((control) => [control.key, control]));
  const getOption = (key) => {
    const value = locks[key];
    if (!value) return null;
    return controlMap.get(key)?.options?.find((option) => option.id === value) || null;
  };

  return Object.fromEntries(
    Object.entries(STRUCTURED_CONTROL_KEYS).map(([section, keys]) => [
      section,
      keys.map(getOption).filter(Boolean),
    ])
  );
}

export function normalizePromptText(text) {
  return String(text || '').toLowerCase().replace(/\s+/g, ' ').trim();
}

export function findBestOptionMatch(options, normalizedPrompt) {
  return [...(options || [])]
    .filter((option) => option?.id && option?.en && option.zh !== '全無')
    .flatMap((option) => [option.en, ...(option.meta?.legacyPromptAliases || [])]
      .map((promptText) => ({ option, normalizedText: normalizePromptText(promptText) })))
    .filter((entry) => entry.normalizedText)
    .sort((a, b) => b.normalizedText.length - a.normalizedText.length)
    .find((entry) => normalizedPrompt.includes(entry.normalizedText))?.option || null;
}

function findWearableTargetColorMatch(options, prompt, target) {
  return (options || []).filter(option => option.zh !== '全無').map(option => {
    const syntax = option.meta?.wearableColorSyntax;
    const phrase = syntax ? [target, syntax.prefix ? `in ${syntax.prefix}` : '',
      syntax.detail ? `with ${syntax.detail}` : ''].filter(Boolean).join(' ')
      : `${target} in ${option.en}`;
    return { option, phrase: normalizePromptText(phrase) };
  }).sort((a, b) => b.phrase.length - a.phrase.length)
    .find(entry => prompt.includes(entry.phrase))?.option || null;
}

export function parseLocksFromStandardPrompt(promptText, controls) {
  const parsedMidjourneyTail = parseMidjourneyParameterTail(promptText);
  const normalizedPrompt = normalizePromptText(parsedMidjourneyTail.content);
  const locks = createEmptyLocks();
  const wardrobeRecovery = createWardrobeRecoveryContext(promptText);
  const matchedControls = [];
  const controlMap = new Map(controls.map((control) => [control.key, control]));
  const visibleTextSettings = parseZImageVisibleTextSentence(promptText);

  if (visibleTextSettings) {
    Object.assign(locks, visibleTextSettings);
    Z_IMAGE_VISIBLE_TEXT_SELECTION_KEYS.forEach((key) => {
      matchedControls.push({
        key,
        label: controlMap.get(key)?.label || key,
        option: {
          id: String(visibleTextSettings[key]),
          zh: String(visibleTextSettings[key]),
          en: '',
        },
      });
    });
  }

  if (normalizedPrompt) {
    const hasUnderbustSource = controlMap.get('topFitId')?.options.some(item => isUnderbustTopFit(item) && normalizedPrompt.includes(item.en));
    const firstWoman = normalizedPrompt.search(/\b(?:woman 1:|first woman,)/);
    const secondWoman = normalizedPrompt.search(/\b(?:woman 2:|second woman,)/);
    const scopedUnderbustDuo = hasUnderbustSource && firstWoman >= 0 && secondWoman > firstWoman;
    const topPromptForRole = role => !scopedUnderbustDuo ? normalizedPrompt
      : role === 'A' ? normalizedPrompt.slice(firstWoman, secondWoman)
        : role === 'B' ? normalizedPrompt.slice(secondWoman).split(/\b(?:shared expression:|pose and composition:|scene:|lighting:)/)[0] : '';
    // The shorter coat-hem source occurs inside the historical inner-top source.
    // Remove whole inner-top instructions only while matching outerwear styling;
    // a separately selected coat instruction remains available to the parser.
    const innerHem = controlMap.get('topStylingId')?.options.find(option => option.id === 'hem-overlap');
    const outerwearStylingPrompt = [innerHem?.en, ...(innerHem?.meta?.legacyPromptAliases || [])]
      .filter(Boolean).reduce((text, source) => text.replaceAll(normalizePromptText(source), ''), normalizedPrompt);
    controls.forEach((control) => {
      if (control.compatibilityOnly) return;
      const topControl = scopedUnderbustDuo && control.key.match(/^top(?:Fit|Styling)?([AB]?)Id$/);
      const option = findBestOptionMatch(control.options,
        topControl ? topPromptForRole(topControl[1])
          : /^outerwear[AB]?StylingId$/.test(control.key) ? outerwearStylingPrompt
            : wardrobeItemRecoveryScope(control.key, wardrobeRecovery, normalizedPrompt));
      if (!option) return;
      locks[control.key] = option.id;
      matchedControls.push({ key: control.key, label: control.label, option });
    });
    for (const role of ['', 'A', 'B']) {
      const topPrompt = topPromptForRole(role);
      const topMatch = matchResolvedUnderbustTop(topPrompt,
        controlMap.get(`top${role}Id`)?.options || [], controlMap.get(`topFit${role}Id`)?.options || []);
      if (topMatch) {
        const naturalHem = topPrompt.includes(UNDERBUST_UNTUCKED_SOURCE)
          ? controlMap.get(`topStyling${role}Id`)?.options.find(item => item.id === 'untucked') : null;
        for (const [key, option] of [[`top${role}Id`, topMatch.top], [`topFit${role}Id`, topMatch.fit],
          ...(naturalHem ? [[`topStyling${role}Id`, naturalHem]] : [])]) {
          locks[key] = option.id;
          const index = matchedControls.findIndex(entry => entry.key === key);
          const entry = { key, label: controlMap.get(key)?.label || key, option };
          if (index >= 0) matchedControls[index] = entry;
          else matchedControls.push(entry);
        }
      }
      const top = controlMap.get(`top${role}Id`)?.options.find(item => item.id === locks[`top${role}Id`]);
      // Read only this authored target from each person's new source. The tie's
      // fixed black detail is not a shirt swatch; historical prose stays on the
      // existing matcher when it lacks the new fixed-detail source.
      const colorPrompt = role && firstWoman >= 0 && secondWoman > firstWoman
        ? role === 'A' ? normalizedPrompt.slice(firstWoman, secondWoman)
          : normalizedPrompt.slice(secondWoman).split(/\b(?:shared expression:|pose and composition:|scene:|lighting:)/)[0]
        : topPrompt;
      if (top?.meta?.wearableColorTarget && /\bshort soft black necktie\b/.test(colorPrompt)) {
        const key = role ? `top${role}ColorId` : 'topColorId';
        const colorControl = controlMap.get(key);
        const color = findWearableTargetColorMatch(colorControl?.options, colorPrompt, top.meta.wearableColorTarget)
          || colorControl?.options.find(item => item.zh === '全無');
        if (color) {
          locks[key] = color.id;
          const index = matchedControls.findIndex(entry => entry.key === key);
          const entry = { key, label: colorControl.label, option: color };
          if (index >= 0) matchedControls[index] = entry;
          else matchedControls.push(entry);
        }
      }
      const itemKey = `outerwear${role}Id`;
      const fitKey = `outerwear${role}FitId`;
      const itemControl = controlMap.get(itemKey);
      const fitControl = controlMap.get(fitKey);
      const itemPrompt = wardrobeItemRecoveryScope(itemKey, wardrobeRecovery, normalizedPrompt);
      const match = matchResolvedOuterwear(itemPrompt, itemControl?.options || [], fitControl?.options || []);
      // Longer historical source aliases keep their original item identity.
      const existing = itemControl?.options.find(item => item.id === locks[itemKey]);
      const hasHistoricalSource = existing && [existing.en, ...(existing.meta?.legacyPromptAliases || [])]
        .some(source => normalizePromptText(source).length > (match?.phrase.length || 0)
          && itemPrompt.includes(normalizePromptText(source)));
      if (!match || hasHistoricalSource) continue;
      for (const [key, option] of [[itemKey, match.item], [fitKey, match.fit]]) {
        if (!option) continue;
        locks[key] = option.id;
        const index = matchedControls.findIndex(entry => entry.key === key);
        const entry = { key, label: controlMap.get(key)?.label || key, option };
        if (index >= 0) matchedControls[index] = entry;
        else matchedControls.push(entry);
      }
    }
  }

  if (normalizedPrompt) {
    const framing = controlMap.get('framingId')?.options.find(option => option.id === locks.framingId);
    if (isHeadDominantFraming(framing)) {
      const angleControl = controlMap.get('angleId');
      const angle = matchHeadDominantAngle(normalizedPrompt, angleControl?.options || []);
      if (angle) {
        locks.angleId = angle.id;
        const oldMatch = matchedControls.findIndex(match => match.key === 'angleId');
        if (oldMatch >= 0) matchedControls.splice(oldMatch, 1);
        matchedControls.push({ key: 'angleId', label: angleControl.label, option: angle });
      }
    }
  }

  if (parsedMidjourneyTail.matched) {
    // A ratio equal to the parsed framing's automatic MJ ratio was derived, not
    // chosen: keep PAGE1 empty and F on "follow PAGE1" so regeneration matches.
    const derivedAspectRatio = framingAspectRatioForSelection(
      locks,
      controlMap.get('framingId')?.options || [],
      controlMap.get('fixedCompositionSetId')?.options || [],
    );
    const tailFramingId = locks.framingId;
    const tailFramingUnresolved = !controlMap.get('framingId')?.options.some(option => option.id === tailFramingId && option.zh !== '全無');
    const framingVariationSet = (controlMap.get('fixedCompositionSetId')?.options || [])
      .find(option => option.id === locks.fixedCompositionSetId && option.allowsFramingVariation);
    if (derivedAspectRatio && parsedMidjourneyTail.aspectRatio === derivedAspectRatio) {
      parsedMidjourneyTail.aspectRatio = '';
      if (parsedMidjourneyTail.settings) parsedMidjourneyTail.settings.mjAspectRatio = 'page1';
    } else if (framingVariationSet && tailFramingUnresolved && parsedMidjourneyTail.aspectRatio) {
      // Carriage text does not round-trip its crop, so the ratio may have been
      // framing-derived. Keep it as the MJ-only F ratio and never invent a PAGE1 ratio.
      parsedMidjourneyTail.aspectRatio = '';
    }
    if (parsedMidjourneyTail.aspectRatio) {
      // Keep the historical PAGE1 ratio restoration while also restoring the
      // new AI-only F control. Unknown/custom ratios continue to flow through
      // the legacy PAGE1 field and therefore remain renderable.
      locks.aspectRatio = parsedMidjourneyTail.aspectRatio;
    }
    const tailValues = {
      ...parsedMidjourneyTail.settings,
      ...(parsedMidjourneyTail.aspectRatio && !parsedMidjourneyTail.settings?.mjAspectRatio
        ? { mjAspectRatio: parsedMidjourneyTail.aspectRatio }
        : {}),
    };
    for (const parameterId of MIDJOURNEY_PARAMETER_CONTRACT.assembly.parameterOrder) {
      const key = MIDJOURNEY_PARAMETER_CONTRACT.controls[parameterId]?.selectionKey
        || (parameterId === 'aspectRatio' ? 'aspectRatio' : parameterId);
      if (!Object.hasOwn(tailValues, key)) continue;
      const value = tailValues[key];
      locks[key] = value;
      const control = controlMap.get(key);
      const option = control?.options?.find((entry) => entry.id === value) || {
        id: String(value),
        zh: String(value),
        en: '',
      };
      matchedControls.push({
        key,
        label: control?.label || key,
        option,
      });
    }
  }

  const specifiedAction = SPECIFIED_ACTION_CONCRETE_OPTIONS.find(option => normalizedPrompt.includes(normalizePromptText(option.en)));
  if (specifiedAction) {
    locks.specifiedActionId = specifiedAction.id;
    locks.poseBaseId = specifiedAction.baseId;
    locks.poseOrientationId = specifiedAction.orientationId;
  }
  for (const [key, option] of recoverWardrobeColors(wardrobeRecovery, locks, controls)) {
    // Retain explicit silence already established by an authored fixed-detail rule.
    if (option.zh === '全無' && locks[key] === option.id) continue;
    locks[key] = option.zh === '全無' ? '' : option.id;
    const index = matchedControls.findIndex(entry => entry.key === key);
    if (index >= 0) matchedControls.splice(index, 1);
    if (option.zh !== '全無') matchedControls.push({ key, label: controlMap.get(key)?.label || key, option });
  }
  return { locks, matchedControls };
}

export function buildRestoreLocks(nextLocks, controls, { restoringSelection = true } = {}) {
  const restoredLocks = { ...createEmptyLocks(), ...nextLocks };

  controls.forEach((control) => {
    if (nextLocks.captureMode === 'observation' && nextLocks.observationCapture?.personSource === 'full-body'
      && isImportedPersonKey(control.key) && Object.hasOwn(nextLocks, control.key)) return;
    if (/^bodyType[AB]?Id$/.test(control.key)) {
      const value = restoredLocks[control.key];
      const current = control.options?.some(option => option.id === value);
      const legacy = !current && control.options?.find(option => option.legacyIds?.includes(value));
      if (legacy) restoredLocks[control.key] = legacy.id;
    }
    if (restoredLocks[control.key]) return;
    const noneOption = control.options?.find((option) => option.zh === '全無');
    if (noneOption) restoredLocks[control.key] = noneOption.id;
  });

  return reconcilePage1SingleWardrobeLocks({
    previousLocks: {},
    candidateLocks: restoredLocks,
    lockControls: controls,
    restoringSelection,
  });
}

export function mergeFavoritePrompts(existingPrompts, importedPrompts) {
  const importedIds = new Set(importedPrompts.map((item) => item.id));
  return [
    ...importedPrompts,
    ...existingPrompts.filter((item) => !importedIds.has(item.id)),
  ];
}

export function toShortPromptId(id) {
  return `#${String(id).slice(-6).toUpperCase()}`;
}

export function createLineage(prompt) {
  return {
    rootId: prompt.id,
    rootShortId: toShortPromptId(prompt.id),
    parentId: null,
    parentShortId: '',
    version: 1,
    remixCount: 0,
    lastMode: 'original',
    lastLocked: [],
  };
}

export function parseExportedMarkdownPrompt(markdownText, controls, fallbackId) {
  const snapshot = decodePage1MarkdownSnapshot(markdownText, controls);
  if (snapshot) {
    const text = String(markdownText).replace(/\r\n/g, '\n');
    const header = text.slice(text.indexOf(' -->\n') + 5).split('\n\n## ')[0];
    const summary = header.match(/^\*\*Summary:\*\*[^\S\r\n]*(.*)$/m)?.[1]?.trim();
    if (!summary) throw new Error('missing markdown summary');
    const prompt = {
      id: fallbackId || `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      date: new Date().toISOString(), source: 'page1',
      sourceLabel: header.match(/^\*\*Source:\*\*[^\S\r\n]*(.*)$/m)?.[1]?.trim() || '',
      summary, summaryFields: parseSummaryFields(summary), ...snapshot.outputs,
      promptLabels: snapshot.promptLabels, selection: snapshot.selection,
      accessoryRestoreNotices: accessoryRestoreNotices(snapshot.selection),
      structured: buildImportedStructured(snapshot.selection, controls),
    };
    return { ...prompt, lineage: createLineage(prompt) };
  }
  const text = String(markdownText || '').replace(/\r\n/g, '\n');
  const sourceMatch = text.match(/\*\*Source:\*\*\s*(.+)/);
  const summaryMatch = text.match(/\*\*Summary:\*\*\s*(.+)/);
  const actionPromptMatch = text.match(/## Action Prompt\n```text\n([\s\S]*?)\n```/);

  if (actionPromptMatch && /動作姿勢|Action Pose/i.test(sourceMatch?.[1] || text)) {
    const actionPrompt = actionPromptMatch[1].trim();
    const matchedCard = ACTION_POSE_CARDS.find((card) => (
      normalizePromptText(card.actionPrompt) === normalizePromptText(actionPrompt)
    ));
    if (!matchedCard) throw new Error('unknown action pose card');

    const prompt = buildActionPoseSavedCard({ mode: matchedCard.mode, selectedCardId: matchedCard.id });
    if (!prompt) throw new Error('invalid action pose card');
    const importedPrompt = {
      ...prompt,
      id: fallbackId || prompt.id,
      date: new Date().toISOString(),
      summary: summaryMatch?.[1]?.trim() || prompt.summary,
    };
    return { ...importedPrompt, lineage: createLineage(importedPrompt) };
  }

  const midjourneyMatch = text.match(/## (?:AI Prompt|Midjourney Prompt)\n```text\n([\s\S]*?)\n```/);
  const grokMatch = text.match(/## (?:Gpt|Grok Structured Prompt)\n```text\n([\s\S]*?)\n```/);
  const zImageMatch = text.match(/## (?:Grok\/Z-Image|Z-Image(?: Prompt)?)\n```text\n([\s\S]*?)\n```/);
  const nanoBananaMatch = text.match(/## Nano Banana 2\.1\n```text\n([\s\S]*?)\n```/);
  if (!summaryMatch || !midjourneyMatch || !grokMatch) {
    throw new Error('missing required markdown sections');
  }

  const summary = summaryMatch[1].trim();
  const midjourneyPrompt = midjourneyMatch[1].trim();
  const grokPrompt = grokMatch[1].trim();
  const zImagePrompt = zImageMatch?.[1]?.trim() || '';
  const parsed = parseLocksFromStandardPrompt(
    `${grokPrompt}\n${zImagePrompt}\n${midjourneyPrompt}`,
    controls,
  );
  if (parsed.matchedControls.length === 0) {
    throw new Error('no recoverable controls found in prompt');
  }

  const silenceMatch = text.match(/<!-- VPStudio Optional Silence: (\{[^\n]*\}) -->/);
  if (silenceMatch) {
    try {
      const silenceLocks = JSON.parse(silenceMatch[1]);
      for (const control of controls) {
        if (!OPTIONAL_SILENCE_LOCK_PATTERN.test(control.key)) continue;
        const value = silenceLocks[control.key];
        if (control.options?.some((option) => option.id === value && option.zh === '全無')) parsed.locks[control.key] = value;
      }
    } catch { /* Older prose remains recoverable when optional metadata is invalid. */ }
  }
  const captureMatch = text.match(/<!-- VPStudio Observation Capture: (\{[^\n]*\}) -->/);
  if (captureMatch) {
    const captureSelection = normalizeLocks(JSON.parse(captureMatch[1]), controls);
    if (captureSelection.captureMode !== 'observation') throw new Error('invalid observation capture metadata');
    Object.assign(parsed.locks, captureSelection);
  }
  const selection = buildRestoreLocks(parsed.locks, controls, { restoringSelection: Boolean(captureMatch) });
  const prompt = {
    id: fallbackId || `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    date: new Date().toISOString(),
    summary,
    accessoryRestoreNotices: accessoryRestoreNotices(parsed.locks),
    summaryFields: parseSummaryFields(summary),
    midjourneyPrompt,
    grokPrompt,
    zImagePrompt,
    ...(nanoBananaMatch ? { nanoBananaPrompt: nanoBananaMatch[1] } : {}),
    selection,
    structured: buildImportedStructured(selection, controls),
  };
  return { ...prompt, lineage: createLineage(prompt) };
}

export function compactPromptSelection(selection) {
  if (!selection || typeof selection !== 'object') return null;

  const normalized = normalizeLocks({ ...createEmptyLocks(), ...selection });
  return Object.fromEntries(
    Object.entries(normalized).filter(([key, value]) => {
      if (key === 'subjectCount' || key === 'aspectRatio') return true;
      if (normalized.captureMode === 'observation' && normalized.observationCapture?.personSource === 'full-body' && isImportedPersonKey(key)) return true;
      if (['specialSubjectId', 'characterProfileId', 'importedWorldSceneMode', 'topBottomPaletteId'].includes(key) && value === 'none') return false;
      return Array.isArray(value) ? value.length > 0 : Boolean(value);
    })
  );
}

export function sanitizeStoredPrompt(prompt, controls = getLockControls()) {
  if (!prompt || typeof prompt !== 'object' || !prompt.id) return null;

  const source = String(prompt.source || 'page1');
  const rawSelection = prompt.selection && typeof prompt.selection === 'object' ? prompt.selection : null;
  const selection = ['page1', 'actionPose'].includes(source) && rawSelection
    ? normalizeLocks({ ...createEmptyLocks(), ...rawSelection })
    : null;
  const summaryFields = prompt.summaryFields && typeof prompt.summaryFields === 'object'
    ? prompt.summaryFields
    : parseSummaryFields(prompt.summary);
  const structured = prompt.structured && typeof prompt.structured === 'object'
    ? prompt.structured
    : (selection ? buildImportedStructured(selection, controls) : {});

  return {
    id: prompt.id,
    accessoryRestoreNotices: [...new Set([...(prompt.accessoryRestoreNotices || []), ...accessoryRestoreNotices(rawSelection || {})])],
    source,
    sourceLabel: String(prompt.sourceLabel || ''),
    date: prompt.date || new Date().toISOString(),
    summary: String(prompt.summary || ''),
    summaryFields,
    midjourneyPrompt: String(prompt.midjourneyPrompt || ''),
    grokPrompt: String(prompt.grokPrompt || ''),
    zImagePrompt: String(prompt.zImagePrompt || ''),
    ...(typeof prompt.nanoBananaPrompt === 'string' ? { nanoBananaPrompt: prompt.nanoBananaPrompt } : {}),
    extraPrompts: Array.isArray(prompt.extraPrompts)
      ? prompt.extraPrompts
        .filter((entry) => entry?.id && entry?.label && entry?.text)
        .map((entry) => ({ id: String(entry.id), label: String(entry.label), text: String(entry.text) }))
      : [],
    promptLabels: prompt.promptLabels && typeof prompt.promptLabels === 'object' ? prompt.promptLabels : null,
    selection,
    structured,
    profile: prompt.profile && typeof prompt.profile === 'object' ? prompt.profile : null,
    lineage: prompt.lineage && typeof prompt.lineage === 'object' ? prompt.lineage : null,
    remixMeta: prompt.remixMeta && typeof prompt.remixMeta === 'object' ? prompt.remixMeta : null,
    sourceProject: String(prompt.sourceProject || ''),
    sourceId: String(prompt.sourceId || ''),
    sourceFileName: String(prompt.sourceFileName || ''),
    sourceTags: Array.isArray(prompt.sourceTags)
      ? prompt.sourceTags
        .map((tag) => normalizeSourceTag(tag, tag?.category || getSourceTagCategory(source)))
        .filter(Boolean)
      : [],
  };
}

export function sanitizeStoredPromptCollection(items) {
  return Array.isArray(items) ? items.map((item) => sanitizeStoredPrompt(item)).filter(Boolean) : [];
}

export function serializeFavoritePrompt(prompt) {
  const sanitized = sanitizeStoredPrompt(prompt);
  if (!sanitized) return null;

  return {
    v: FAVORITES_STORAGE_VERSION,
    an: sanitized.accessoryRestoreNotices,
    i: sanitized.id,
    o: sanitized.source,
    b: sanitized.sourceLabel,
    d: sanitized.date,
    s: sanitized.summary,
    m: sanitized.midjourneyPrompt,
    g: sanitized.grokPrompt,
    z: sanitized.zImagePrompt,
    ...(sanitized.nanoBananaPrompt !== undefined ? { nb: sanitized.nanoBananaPrompt } : {}),
    e: sanitized.extraPrompts,
    y: sanitized.promptLabels,
    l: compactPromptSelection(sanitized.selection),
    p: sanitized.profile,
    n: sanitized.lineage,
    r: sanitized.remixMeta,
    q: sanitized.sourceProject,
    u: sanitized.sourceId,
    f: sanitized.sourceFileName,
    t: sanitized.sourceTags,
  };
}

export function deserializeFavoritePrompt(record) {
  if (!record || typeof record !== 'object') return null;

  if (READABLE_FAVORITES_STORAGE_VERSIONS.includes(record.v) && record.i) {
    return sanitizeStoredPrompt({
      id: record.i,
      accessoryRestoreNotices: record.an,
      source: record.o,
      sourceLabel: record.b,
      date: record.d,
      summary: record.s,
      midjourneyPrompt: record.m,
      grokPrompt: record.g,
      zImagePrompt: record.z,
      ...(typeof record.nb === 'string' ? { nanoBananaPrompt: record.nb } : {}),
      extraPrompts: record.e,
      promptLabels: record.y,
      selection: record.l,
      profile: record.p,
      lineage: record.n,
      remixMeta: record.r,
      sourceProject: record.q,
      sourceId: record.u,
      sourceFileName: record.f,
      sourceTags: record.t,
    });
  }

  return sanitizeStoredPrompt(record);
}

export function deserializeFavoritePromptCollection(items) {
  return Array.isArray(items) ? items.map(deserializeFavoritePrompt).filter(Boolean) : [];
}

